/* Named selectors and community filters. IDs remain exact strings throughout. */
let pickerSequence=0;
function enhanceIdPickers(){
 for(const input of $$('input[name=allowed], #roles-form input')){
  if(input.dataset.enhanced)continue;input.dataset.enhanced='true';
  const kind=input.name==='allowed'?'channel':'role',items=(kind==='role'?guild()?.roles:guild()?.channels)||[];
  const previous=input.closest('label');if(!previous)continue;
  const caption=previous.childNodes[0]?.textContent.trim().replace('Kanal-IDs','Kanäle')||'Auswahl';
  const group=document.createElement('fieldset');group.className='named-picker';
  group.innerHTML=`<legend>${esc(caption)}</legend><p class="small">${kind==='channel'?'Ohne Auswahl ist der Befehl in allen Kanälen erlaubt.':'Rollen anhand ihres Namens auswählen. Namen und IDs bleiben gemeinsam sichtbar.'}</p><div class="picker-selection"></div><details><summary>Auswahl bearbeiten</summary><label class="picker-search-label">${kind==='role'?'Rolle':'Kanal'} suchen<input type="search" placeholder="Name oder ID" class="picker-search"></label><div class="picker-options"></div><details class="picker-manual"><summary>Fehlende ID ergänzen</summary><label>Discord-ID<input class="picker-manual-id" inputmode="numeric" placeholder="Nur wenn das Objekt noch nicht geladen ist"></label><button type="button" class="quiet picker-add">Ergänzen</button></details></details>`;
  previous.replaceWith(group);input.type='hidden';group.append(input);
  const selection=new Set(input.value.split(/[\s,;]+/).filter(Boolean));
  const sync=()=>{input.value=[...selection].join(', ');$('.picker-selection',group).innerHTML=selection.size?[...selection].map(id=>`<div class="picker-chip">${identity(items.find(x=>String(x.id)===id)?.name,id)}<button type="button" class="picker-remove" data-remove-value="${esc(id)}" aria-label="Auswahl entfernen" ${input.disabled?'disabled':''}>×</button></div>`).join(''):'<span class="small muted">'+(kind==='channel'?'Alle Kanäle':'Keine Rolle ausgewählt')+'</span>';$$('[data-remove-value]',group).forEach(b=>b.onclick=()=>{selection.delete(b.dataset.removeValue);sync();draw();});};
  const draw=()=>{const term=$('.picker-search',group).value.trim().toLocaleLowerCase('de');const matching=items.filter(x=>(x.name+' '+x.id).toLocaleLowerCase('de').includes(term));$('.picker-options',group).innerHTML=matching.slice(0,150).map(x=>`<div class="picker-option"><input type="checkbox" aria-label="${esc(x.name)} auswählen" data-value="${esc(x.id)}" ${selection.has(String(x.id))?'checked':''} ${input.disabled?'disabled':''}>${identity(x.name,x.id)}</div>`).join('')||'<p class="small">Kein passender Eintrag geladen.</p>';if(matching.length>150)$('.picker-options',group).insertAdjacentHTML('beforeend','<p class="small">Bitte die Suche eingrenzen, um weitere Treffer zu sehen.</p>');$$('input[data-value]',group).forEach(c=>c.onchange=()=>{c.checked?selection.add(c.dataset.value):selection.delete(c.dataset.value);sync();});};
  $('.picker-search',group).oninput=draw;$('.picker-add',group).disabled=input.disabled;$('.picker-add',group).onclick=()=>{const field=$('.picker-manual-id',group),id=field.value.trim();if(!/^\d{15,22}$/.test(id)){toast('Bitte eine vollständige Discord-ID eingeben.',true);return;}selection.add(id);field.value='';sync();draw();};
  sync();draw();
 }
}

function memberMatches(member,query,roleIds,category,mode='any'){
 const names=(member.name||'')+' '+(member.username||'')+' '+member.id;
 if(query&&!names.toLocaleLowerCase('de').includes(query))return false;
 if(category==='admins'&&!member.admin)return false;
 if(category==='bots'&&!member.bot)return false;
 if(category==='people'&&member.bot)return false;
 const owned=(member.role_ids||[]).map(String);
 return !roleIds.length||(mode==='all'?roleIds.every(id=>owned.includes(id)):roleIds.some(id=>owned.includes(id)));
}
function communityMembers(){
 const g=guild(),selected=new Set();
 $('#content').innerHTML=`<section class="panel"><div class="panel-head"><div><h2>Deine Community finden</h2><p>Die Auswahl gilt für <strong>${esc(g.name)}</strong>. Standardmäßig werden alle Mitglieder angezeigt.</p></div><span class="badge">${number((g.members||[]).length)} geladen</span></div><div class="form-grid"><label>Mitglied oder Rolle suchen<input id="member-search" type="search" placeholder="Name oder vollständige ID"></label><label>Kategorie<select id="member-category"><option value="all">Alle Mitglieder</option><option value="admins">Nur Administratoren</option><option value="people">Nur Menschen</option><option value="bots">Nur Bots</option></select></label></div><div class="filter-heading"><h3>Nach Rollen filtern</h3><button id="role-filter-reset" type="button" class="quiet">Alle anzeigen</button></div><p class="small">Klicke eine oder mehrere Rollen an. „Administratoren“ richtet sich nach der Discord-Berechtigung, nicht nach dem Rollennamen.</p><div class="inline-fields"><label>Rollen suchen<input id="role-filter-search" type="search" placeholder="z. B. Moderator"></label><label>Bei mehreren Rollen<select id="role-match"><option value="any">Mindestens eine gewählte Rolle</option><option value="all">Alle gewählten Rollen</option></select></label></div><div id="role-filters" class="role-filters"></div><div id="selected-role-filters" class="identity-list"></div><p class="small" id="member-loading-note"></p></section><div class="grid-2"><section class="panel"><h2>Mitglieder <small id="member-count"></small></h2><div id="member-list"></div></section><section class="panel"><h2>Serverrollen <small id="role-count"></small></h2><div id="role-list"></div></section></div>`;
 const renderRoleFilters=()=>{const term=$('#role-filter-search').value.toLocaleLowerCase('de');$('#role-filters').innerHTML=(g.roles||[]).filter(r=>(r.name+' '+r.id).toLocaleLowerCase('de').includes(term)).map(r=>`<button type="button" class="role-filter ${selected.has(String(r.id))?'selected':''}" data-role-filter="${esc(r.id)}" aria-pressed="${selected.has(String(r.id))}" title="${esc(r.name)} · ${esc(r.id)}">${esc(currentUser?.preferences?.identity_order==='id'?r.id:r.name)} <small>${esc(currentUser?.preferences?.identity_order==='id'?r.name:r.id)}</small></button>`).join('');$$('[data-role-filter]').forEach(b=>b.onclick=()=>{const id=b.dataset.roleFilter;selected.has(id)?selected.delete(id):selected.add(id);renderRoleFilters();draw();});};
 const draw=()=>{const query=$('#member-search').value.trim().toLocaleLowerCase('de'),category=$('#member-category').value;const filtered=(g.members||[]).filter(m=>memberMatches(m,query,[...selected],category,$('#role-match').value));$('#member-list').innerHTML=filtered.map(m=>`<article class="entity-row">${identity(m.name,m.id)}<div class="member-tags">${m.admin?'<span>Administrator</span>':''}${m.bot?'<span>Bot</span>':''}${(m.role_ids||[]).filter(id=>String(id)!==String(g.id)).slice(0,5).map(id=>`<span>${esc((g.roles||[]).find(r=>String(r.id)===String(id))?.name||'Nicht verfügbare Rolle')}</span>`).join('')}</div></article>`).join('')||'<p>Keine Mitglieder passen zu dieser Auswahl.</p>';$('#member-count').textContent=filtered.length+' / '+(g.members||[]).length;
  const roles=(g.roles||[]).filter(r=>(r.name+' '+r.id).toLocaleLowerCase('de').includes(query)&&(!selected.size||selected.has(String(r.id))));$('#role-list').innerHTML=roles.map(r=>`<div class="entity-row">${identity(r.name,r.id)}<small>${(g.members||[]).filter(m=>(m.role_ids||[]).map(String).includes(String(r.id))).length} geladene Mitglieder</small></div>`).join('')||'<p>Keine passenden Rollen.</p>';$('#role-count').textContent=roles.length+' / '+(g.roles||[]).length;$('#selected-role-filters').innerHTML=[...selected].map(id=>identity((g.roles||[]).find(r=>String(r.id)===id)?.name,id)).join('');
  const total=g.member_count??g.stats?.members??(g.members||[]).length;$('#member-loading-note').textContent=(g.members||[]).length<total?`${(g.members||[]).length} von ${total} Mitgliedern geladen. Der Bot lädt die Servermitglieder nach; danach oben aktualisieren.`:'Alle derzeit vom Server gemeldeten Mitglieder sind geladen.';
 };
 $('#member-search').oninput=draw;$('#member-category').onchange=draw;$('#role-match').onchange=draw;$('#role-filter-search').oninput=renderRoleFilters;$('#role-filter-reset').onclick=()=>{selected.clear();$('#member-category').value='all';renderRoleFilters();draw();};renderRoleFilters();draw();
}
